-- Triggers
-- Trigger: trg_convenios_before_insert
DROP TRIGGER IF EXISTS `trg_convenios_before_insert`;
DELIMITER ;;
CREATE DEFINER=`myadmin`@`%` TRIGGER `trg_convenios_before_insert` BEFORE INSERT ON `convenios` FOR EACH ROW BEGIN
  -- Si no viene especificado, asigna el siguiente número para la empresa
  IF NEW.nro_acuerdo_marco IS NULL OR NEW.nro_acuerdo_marco = 0 THEN
    SELECT COALESCE(MAX(nro_acuerdo_marco), 0) + 1
      INTO @next_n
      FROM convenios
     WHERE id_empresa = NEW.id_empresa;
    SET NEW.nro_acuerdo_marco = @next_n;
  END IF;
END ;;
DELIMITER ;

-- Trigger: trg_convenios_insert
DROP TRIGGER IF EXISTS `trg_convenios_insert`;
DELIMITER ;;
CREATE DEFINER=`myadmin`@`%` TRIGGER `trg_convenios_insert` AFTER INSERT ON `convenios` FOR EACH ROW BEGIN
    VALUES (NULL, 'CONVENIOS', 'INSERT', NULL, CONCAT('id_convenio=', NEW.id_convenio, ', id_empresa=', NEW.id_empresa), 'TRIGGER');
END ;;
DELIMITER ;

-- Trigger: trg_convenios_before_update
DROP TRIGGER IF EXISTS `trg_convenios_before_update`;
DELIMITER ;;
CREATE DEFINER=`myadmin`@`%` TRIGGER `trg_convenios_before_update` BEFORE UPDATE ON `convenios` FOR EACH ROW BEGIN
  -- No permitir que se cambie manualmente el número dentro de la misma empresa.
  -- Si se cambia la empresa, asigna el siguiente número para la nueva empresa.
  IF NEW.id_empresa <> OLD.id_empresa THEN
    SELECT COALESCE(MAX(nro_acuerdo_marco), 0) + 1
      INTO @next_n
      FROM convenios
     WHERE id_empresa = NEW.id_empresa;
    SET NEW.nro_acuerdo_marco = @next_n;
  ELSE
    SET NEW.nro_acuerdo_marco = OLD.nro_acuerdo_marco;
  END IF;
END ;;
DELIMITER ;

